// Des: Command context: config, paths, state store, browser session, output, alert
// Flo: find + load config > expand paths > open store > launch Chrome on own profile (or mock page) > connect CDP > emit text
// I/O: process Init + Args (main) > Ctx, Stor, Live (CDP link); text on stdout, alert file + stderr
// ===================================================================
const std = @import("std"); const conf = @import("cf-conf-load.zig"); const data = @import("st-stat-data.zig"); const targ = @import("ct-ctrl-args.zig"); const brow = @import("nt-brow-laun.zig"); const cdp = @import("nt-cdpz-sock.zig"); const mock = @import("te-mock-page.zig"); const fixt = @import("te-fixt-html.zig"); const snap = @import("ru-page-snap.zig"); const file = @import("st-stor-file.zig");
const CF = .{ .file = "aa-conf-main.json", .dbnm = "za-stat.db", .alrt = "za-alert.txt", .wait = 30000, .zalo = "chat.zalo.me" };
pub const Ctx = struct { init: std.process.Init, allo: std.mem.Allocator, iozz: std.Io, cfg: conf.Conf, args: targ.Args, stat: []const u8, prof: []const u8 };
pub const Live = struct { gpaz: std.mem.Allocator, bro: brow.Brow, conn: *cdp.Conn, pub fn close(self: *Live) void { self.conn.close(); self.bro.stop(); } };
fn confFind(allo: std.mem.Allocator, iozz: std.Io, args: targ.Args) !conf.Conf { if (args.conf.len > 0) return conf.confLoad(allo, iozz, args.conf); const dirz = std.process.executableDirPathAlloc(iozz, allo) catch "."; const path = try std.fs.path.join(allo, &.{ dirz, CF.file }); if (file.fileHas(iozz, path)) return conf.confLoad(allo, iozz, path); return conf.confLoad(allo, iozz, CF.file); }
pub fn make(init: std.process.Init, args: targ.Args) !Ctx { const allo = init.arena.allocator(); const cfg = try confFind(allo, init.io, args); const home = init.environ_map.get("USERPROFILE") orelse init.environ_map.get("HOME") orelse "."; return .{ .init = init, .allo = allo, .iozz = init.io, .cfg = cfg, .args = args, .stat = try conf.pathHome(allo, home, cfg.stat_dirz_path), .prof = try conf.pathHome(allo, home, cfg.prof_dirz_path) }; }
pub fn emit(ctx: *Ctx, text: []const u8) !void { try std.Io.File.stdout().writeStreamingAll(ctx.iozz, text); }
pub fn emitf(ctx: *Ctx, comptime fmt: []const u8, args: anytype) !void { try emit(ctx, try std.fmt.allocPrint(ctx.allo, fmt, args)); }
pub fn openStor(ctx: *Ctx) !data.Stor { try std.Io.Dir.cwd().createDirPath(ctx.iozz, ctx.stat); const path = try std.fmt.allocPrintSentinel(ctx.allo, "{s}{c}{s}", .{ ctx.stat, std.fs.path.sep, CF.dbnm }, 0); return data.Stor.open(ctx.allo, path); }
pub fn nowMs(ctx: *Ctx) i64 { return @intCast(std.Io.Clock.real.now(ctx.iozz).toMilliseconds()); }
pub fn alert(ctx: *Ctx, msg: []const u8) void { std.debug.print("ALERT: {s}\n", .{msg}); const path = std.fs.path.join(ctx.allo, &.{ ctx.stat, CF.alrt }) catch return; const body = std.fmt.allocPrint(ctx.allo, "{d} {s}\n", .{ nowMs(ctx), msg }) catch return; file.fileAtom(ctx.allo, ctx.iozz, path, body) catch {}; }
pub fn openLive(ctx: *Ctx, headed: bool) !Live { const gpaz = ctx.init.gpa; if (ctx.args.mock) { const mpr = try std.fs.path.join(ctx.allo, &.{ ctx.stat, "mock-prof" }); const mok = try mock.start(gpaz, ctx.iozz, mpr, fixt.chat); return .{ .gpaz = gpaz, .bro = mok.bro, .conn = mok.conn }; } const exe = (try brow.exeFind(gpaz, ctx.iozz, ctx.cfg.brow_exec_path)) orelse return error.NoBrowser; defer gpaz.free(exe); var bro = try brow.launch(gpaz, ctx.iozz, exe, ctx.prof, ctx.cfg.brow_head_mode and !headed, CF.wait); errdefer bro.stop(); const path = try brow.pageWs(gpaz, ctx.iozz, bro.port, CF.wait); defer gpaz.free(path); const conn = try cdp.connect(gpaz, ctx.iozz, bro.port, path, CF.wait); errdefer conn.close(); const href = snap.evalStr(ctx.allo, conn, "location.href") catch ""; if (std.mem.find(u8, href, CF.zalo) == null) try snap.navigate(ctx.allo, conn, ctx.cfg.zalo_page_urlz, CF.wait); return .{ .gpaz = gpaz, .bro = bro, .conn = conn }; }
